import{_ as n,o as s,c as a,a2 as t}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"事件监听 (Events)","description":"","frontmatter":{},"headers":[],"relativePath":"events.md","filePath":"events.md","lastUpdated":1669882888000}'),p={name:"events.md"};function i(l,e,o,c,d,v){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="事件监听-events" tabindex="-1">事件监听 (Events)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>events模块提供了监听手机通知、按键、触摸的接口. 您可以用他配合自动操作函数完成自动化工作.</p><p>events本身是一个<a href="#events_eventemitter">EventEmiiter</a>, 但内置了一些事件、包括按键事件、通知事件、Toast事件等.</p><p>需要注意的是, 事件的处理是单线程的, 并且仍然在原线程执行, 如果脚本主体或者其他事件处理中有耗时操作、轮询等, 则事件将无法得到及时处理（会进入事件队列等待脚本主体或其他事件处理完成才执行）. 例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>events.observeNotification();</span></span>
<span class="line"><span>events.on(&#39;toast&#39;, function(t){</span></span>
<span class="line"><span>    //这段代码将得不到执行</span></span>
<span class="line"><span>    log(t);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>while(true){</span></span>
<span class="line"><span>    //死循环</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="events-emitter" tabindex="-1">events.emitter()</h2><p>返回一个新的<a href="#events_eventemitter">EventEmitter</a>. 这个EventEmitter没有内置任何事件.</p><h2 id="events-observekey" tabindex="-1">events.observeKey()</h2><p>启用按键监听, 例如音量键、Home键. 按键监听使用无障碍服务实现, 如果无障碍服务未启用会抛出异常并提示开启.</p><p>只有这个函数成功执行后, <code>onKeyDown</code>, <code>onKeyUp</code>等按键事件的监听才有效.</p><p>该函数在安卓4.3以上才能使用.</p><h2 id="events-onkeydown-keyname-listener" tabindex="-1">events.onKeyDown(keyName, listener)</h2><ul><li><code>keyName</code> {string} 要监听的按键名称</li><li><code>listener</code> {Function} 按键监听器. 参数为一个<a href="#events_keyevent">KeyEvent</a>.</li></ul><p>注册一个按键监听函数, 当有keyName对应的按键被按下会调用该函数. 可用的按键名称参见<a href="#events_keys">Keys</a>.</p><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//启用按键监听</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>//监听音量上键按下</span></span>
<span class="line"><span>events.onKeyDown(&quot;volume_up&quot;, function(event){</span></span>
<span class="line"><span>    toast(&quot;音量上键被按下了&quot;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>//监听菜单键按下</span></span>
<span class="line"><span>events.onKeyDown(&quot;menu&quot;, function(event){</span></span>
<span class="line"><span>    toast(&quot;菜单键被按下了&quot;);</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="events-onkeyup-keyname-listener" tabindex="-1">events.onKeyUp(keyName, listener)</h2><ul><li><code>keyName</code> {string} 要监听的按键名称</li><li><code>listener</code> {Function} 按键监听器. 参数为一个<a href="#events_keyevent">KeyEvent</a>.</li></ul><p>注册一个按键监听函数, 当有keyName对应的按键弹起会调用该函数. 可用的按键名称参见<a href="#events_keys">Keys</a>.</p><p>一次完整的按键动作包括了按键按下和弹起. 按下事件会在手指按下一个按键的&quot;瞬间&quot;触发, 弹起事件则在手指放开这个按键时触发.</p><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//启用按键监听</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>//监听音量下键弹起</span></span>
<span class="line"><span>events.onKeyDown(&quot;volume_down&quot;, function(event){</span></span>
<span class="line"><span>    toast(&quot;音量上键弹起&quot;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>//监听Home键弹起</span></span>
<span class="line"><span>events.onKeyDown(&quot;home&quot;, function(event){</span></span>
<span class="line"><span>    toast(&quot;Home键弹起&quot;);</span></span>
<span class="line"><span>    exit();</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="events-oncekeydown-keyname-listener" tabindex="-1">events.onceKeyDown(keyName, listener)</h2><ul><li><code>keyName</code> {string} 要监听的按键名称</li><li><code>listener</code> {Function} 按键监听器. 参数为一个<a href="#events_keyevent">KeyEvent</a></li></ul><p>注册一个按键监听函数, 当有keyName对应的按键被按下时会调用该函数, 之后会注销该按键监听器.</p><p>也就是listener只有在onceKeyDown调用后的第一次按键事件被调用一次.</p><h2 id="events-oncekeyup-keyname-listener" tabindex="-1">events.onceKeyUp(keyName, listener)</h2><ul><li><code>keyName</code> {string} 要监听的按键名称</li><li><code>listener</code> {Function} 按键监听器. 参数为一个<a href="#events_keyevent">KeyEvent</a></li></ul><p>注册一个按键监听函数, 当有keyName对应的按键弹起时会调用该函数, 之后会注销该按键监听器.</p><p>也就是listener只有在onceKeyUp调用后的第一次按键事件被调用一次.</p><h2 id="events-removeallkeydownlisteners-keyname" tabindex="-1">events.removeAllKeyDownListeners(keyName)</h2><ul><li><code>keyName</code> {string} 按键名称</li></ul><p>删除该按键的KeyDown(按下)事件的所有监听.</p><h2 id="events-removeallkeyuplisteners-keyname" tabindex="-1">events.removeAllKeyUpListeners(keyName)</h2><ul><li><code>keyName</code> {string} 按键名称</li></ul><p>删除该按键的KeyUp(弹起)事件的所有监听.</p><h2 id="events-setkeyinterceptionenabled-key-enabled" tabindex="-1">events.setKeyInterceptionEnabled([key, ]enabled)</h2><ul><li><code>enabled</code> {boolean}</li><li><code>key</code> {string} 要屏蔽的按键</li></ul><p>设置按键屏蔽是否启用. 所谓按键屏蔽指的是, 屏蔽原有按键的功能, 例如使得音量键不再能调节音量, 但此时仍然能通过按键事件监听按键.</p><p>如果不加参数key则会屏蔽所有按键.</p><p>例如, 调用<code>events.setKeyInterceptionEnabled(true)</code>会使系统的音量、Home、返回等键不再具有调节音量、回到主页、返回的作用, 但此时仍然能通过按键事件监听按键.</p><p>该函数通常于按键监听结合, 例如想监听音量键并使音量键按下时不弹出音量调节框则为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.setKeyInterceptionEnabled(&quot;volume_up&quot;, true);</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>events.onKeyDown(&quot;volume_up&quot;, ()=&gt;{</span></span>
<span class="line"><span>    log(&quot;音量上键被按下&quot;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>只要有一个脚本屏蔽了某个按键, 该按键便会被屏蔽；当脚本退出时, 会自动解除所有按键屏蔽.</p><h2 id="events-observetouch" tabindex="-1">events.observeTouch()</h2><p>启用屏幕触摸监听. （需要root权限）</p><p>只有这个函数被成功执行后, 触摸事件的监听才有效.</p><p>没有root权限调用该函数则什么也不会发生.</p><h2 id="events-settoucheventtimeout-timeout" tabindex="-1">events.setTouchEventTimeout(timeout)</h2><ul><li><code>timeout</code> {number} 两个触摸事件的最小间隔. 单位毫秒. 默认为10毫秒. 如果number小于0, 视为0处理.</li></ul><p>设置两个触摸事件分发的最小时间间隔.</p><p>例如间隔为10毫秒的话, 前一个触摸事件发生并被注册的监听器处理后, 至少要过10毫秒才能分发和处理下一个触摸事件, 这10毫秒之间的触摸将会被忽略.</p><p>建议在满足需要的情况下尽量提高这个间隔. 一个简单滑动动作可能会连续触发上百个触摸事件, 如果timeout设置过低可能造成事件拥堵. 强烈建议不要设置timeout为0.</p><h2 id="events-gettoucheventtimeout" tabindex="-1">events.getTouchEventTimeout()</h2><p>返回触摸事件的最小时间间隔.</p><h2 id="events-ontouch-listener" tabindex="-1">events.onTouch(listener)</h2><ul><li><code>listener</code> {Function} 参数为<a href="./images#images_point">Point</a>的函数</li></ul><p>注册一个触摸监听函数. 相当于<code>on(&quot;touch&quot;, listener)</code>.</p><p>例如:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//启用触摸监听</span></span>
<span class="line"><span>events.observeTouch();</span></span>
<span class="line"><span>//注册触摸监听器</span></span>
<span class="line"><span>events.onTouch(function(p){</span></span>
<span class="line"><span>    //触摸事件发生时, 打印出触摸的点的坐标</span></span>
<span class="line"><span>    log(p.x + &quot;, &quot; + p.y);</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="events-removealltouchlisteners" tabindex="-1">events.removeAllTouchListeners()</h2><p>删除所有事件监听函数.</p><h2 id="事件-key" tabindex="-1">事件: &#39;key&#39;</h2><ul><li><code>keyCode</code> {number} 键值</li><li><code>event</code> {KeyEvent} 事件</li></ul><p>当有按键被按下或弹起时会触发该事件. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>events.on(&quot;key&quot;, function(keyCode, event){</span></span>
<span class="line"><span>    //处理按键事件</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>其中监听器的参数KeyCode包括：</p><ul><li><code>keys.home</code> 主页键</li><li><code>keys.back</code> 返回键</li><li><code>keys.menu</code> 菜单键</li><li><code>keys.volume_up</code> 音量上键</li><li><code>keys.volume_down</code> 音量下键</li></ul><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>events.on(&quot;key&quot;, function(keyCode, event){</span></span>
<span class="line"><span>    if(keyCode == keys.menu &amp;&amp; event.getAction() == event.ACTION_UP){</span></span>
<span class="line"><span>        toast(&quot;菜单键按下&quot;);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="事件-key-down" tabindex="-1">事件: &#39;key_down&#39;</h2><ul><li><code>keyCode</code> {number} 键值</li><li><code>event</code> {KeyEvent} 事件</li></ul><p>当有按键被按下时会触发该事件.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>events.on(&quot;key_down&quot;, function(keyCode, event){</span></span>
<span class="line"><span>    //处理按键按下事件</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="事件-key-up" tabindex="-1">事件: &#39;key_up&#39;</h2><ul><li><code>keyCode</code> {number} 键值</li><li><code>event</code> {KeyEvent} 事件</li></ul><p>当有按键弹起时会触发该事件.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto();</span></span>
<span class="line"><span>events.observeKey();</span></span>
<span class="line"><span>events.on(&quot;key_up&quot;, function(keyCode, event){</span></span>
<span class="line"><span>    //处理按键弹起事件</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="事件-exit" tabindex="-1">事件: &#39;exit\`</h2><p>当脚本正常或者异常退出时会触发该事件. 事件处理中如果有异常抛出, 则立即中止exit事件的处理（即使exit事件有多个处理函数）并在控制台和日志中打印该异常.</p><p>一个脚本停止运行时, 会关闭该脚本的所有悬浮窗, 触发exit事件, 之后再回收资源. 如果exit事件的处理中有死循环, 则后续资源无法得到及时回收. 此时脚本会停留在任务列表, 如果在任务列表中关闭, 则会强制结束exit事件的处理并回收后续资源.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>log(&quot;开始运行&quot;)</span></span>
<span class="line"><span>events.on(&quot;exit&quot;, function(){</span></span>
<span class="line"><span>    log(&quot;结束运行&quot;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>log(&quot;即将结束运行&quot;);</span></span></code></pre></div><h2 id="events-observenotification" tabindex="-1">events.observeNotification()</h2><p>开启通知监听. 例如QQ消息、微信消息、推送等通知.</p><p>通知监听依赖于通知服务, 如果通知服务没有运行, 会抛出异常并跳转到通知权限开启界面. （有时即使通知权限已经开启通知服务也没有运行, 这时需要关闭权限再重新开启一次）</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.observeNotification();</span></span>
<span class="line"><span>events.onNotification(function(notification){</span></span>
<span class="line"><span>    log(notification.getText());</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="events-observetoast" tabindex="-1">events.observeToast()</h2><p>开启Toast监听.</p><p>Toast监听依赖于无障碍服务, 因此此函数会确保无障碍服务运行.</p><h2 id="事件-toast" tabindex="-1">事件: &#39;toast&#39;</h2><ul><li><code>toast</code> {Object} <ul><li><code>getText()</code> 获取Toast的文本内容</li><li><code>getPackageName()</code> 获取发出Toast的应用包名</li></ul></li></ul><p>当有应用发出toast(气泡消息)时会触发该事件. 但Auto.js软件本身的toast除外.</p><p>例如, 要记录发出所有toast的应用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.observeToast();</span></span>
<span class="line"><span>events.onToast(function(toast){</span></span>
<span class="line"><span>    log(&quot;Toast内容: &quot; + toast.getText() + &quot; 包名: &quot; + toast.getPackageName());</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="事件-notification" tabindex="-1">事件: &#39;notification&#39;</h2><ul><li><code>notification</code> <a href="#events_notification">Notification</a> 通知对象</li></ul><p>当有应用发出通知时会触发该事件, 参数为<a href="#events_notification">Notification</a>.</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.observeNotification();</span></span>
<span class="line"><span>events.on(&quot;notification&quot;, function(n){</span></span>
<span class="line"><span>    log(&quot;收到新通知:\\n 标题: %s, 内容: %s, \\n包名: %s&quot;, n.getTitle(), n.getText(), n.getPackageName());</span></span>
<span class="line"><span>});</span></span></code></pre></div><h1 id="notification" tabindex="-1">Notification</h1><p>通知对象, 可以获取通知详情, 包括通知标题、内容、发出通知的包名、时间等, 也可以对通知进行操作, 比如点击、删除.</p><h2 id="notification-number" tabindex="-1">Notification.number</h2><ul><li>{number}</li></ul><p>通知数量. 例如QQ连续收到两条消息时number为2.</p><h2 id="notification-when" tabindex="-1">Notification.when</h2><ul><li>{number}</li></ul><p>通知发出时间的时间戳, 可以用于构造<code>Date</code>对象. 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.observeNotification();</span></span>
<span class="line"><span>events.on(&quot;notification&quot;, function(n){</span></span>
<span class="line"><span>    log(&quot;通知时间为}&quot; + new Date(n.when));</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="notification-getpackagename" tabindex="-1">Notification.getPackageName()</h2><ul><li>返回 {string}</li></ul><p>获取发出通知的应用包名.</p><h2 id="notification-gettitle" tabindex="-1">Notification.getTitle()</h2><ul><li>返回 {string}</li></ul><p>获取通知的标题.</p><h2 id="notification-gettext" tabindex="-1">Notification.getText()</h2><ul><li>返回 {string}</li></ul><p>获取通知的内容.</p><h2 id="notification-click" tabindex="-1">Notification.click()</h2><p>点击该通知. 例如对于一条QQ消息, 点击会进入具体的聊天界面.</p><h2 id="notification-delete" tabindex="-1">Notification.delete()</h2><p>删除该通知. 该通知将从通知栏中消失.</p><h1 id="keyevent" tabindex="-1">KeyEvent</h1><h2 id="keyevent-getaction" tabindex="-1">KeyEvent.getAction()</h2><p>返回事件的动作. 包括：</p><ul><li><code>KeyEvent.ACTION_DOWN</code> 按下事件</li><li><code>KeyEvent.ACTION_UP</code> 弹起事件</li></ul><h2 id="keyevent-getkeycode" tabindex="-1">KeyEvent.getKeyCode()</h2><p>返回按键的键值. 包括：</p><ul><li><code>KeyEvent.KEYCODE_HOME</code> 主页键</li><li><code>KeyEvent.KEYCODE_BACK</code> 返回键</li><li><code>KeyEvent.KEYCODE_MENU</code> 菜单键</li><li><code>KeyEvent.KEYCODE_VOLUME_UP</code> 音量上键</li><li><code>KeyEvent.KEYCODE_VOLUME_DOWN</code> 音量下键</li></ul><h2 id="keyevent-geteventtime" tabindex="-1">KeyEvent.getEventTime()</h2><ul><li>返回 {number}</li></ul><p>返回事件发生的时间戳.</p><h2 id="keyevent-getdowntime" tabindex="-1">KeyEvent.getDownTime()</h2><p>返回最近一次按下事件的时间戳. 如果本身是按下事件, 则与<code>getEventTime()</code>相同.</p><h2 id="keyevent-keycodetostring-keycode" tabindex="-1">KeyEvent.keyCodeToString(keyCode)</h2><p>把键值转换为字符串. 例如KEYCODE_HOME转换为&quot;KEYCODE_HOME&quot;.</p><h1 id="keys" tabindex="-1">keys</h1><p>按键事件中所有可用的按键名称为：</p><ul><li><code>volume_up</code> 音量上键</li><li><code>volume_down</code> 音量下键</li><li><code>home</code> 主屏幕键</li><li><code>back</code> 返回键</li><li><code>menu</code> 菜单键</li></ul><h1 id="eventemitter" tabindex="-1">EventEmitter</h1><h2 id="eventemitter-defaultmaxlisteners" tabindex="-1">EventEmitter.defaultMaxListeners</h2><p>每个事件默认可以注册最多 10 个监听器. 单个 EventEmitter 实例的限制可以使用 emitter.setMaxListeners(n) 方法改变. 所有 EventEmitter 实例的默认值可以使用 EventEmitter.defaultMaxListeners 属性改变.</p><p>设置 EventEmitter.defaultMaxListeners 要谨慎, 因为会影响所有 EventEmitter 实例, 包括之前创建的. 因而, 调用 emitter.setMaxListeners(n) 优先于 EventEmitter.defaultMaxListeners.</p><p>注意, 与Node.js不同, <strong>这是一个硬性限制</strong>. EventEmitter 实例不允许添加更多的监听器, 监听器超过最大数量时会抛出TooManyListenersException.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>emitter.setMaxListeners(emitter.getMaxListeners() + 1);</span></span>
<span class="line"><span>emitter.once(&#39;event&#39;, () =&gt; {</span></span>
<span class="line"><span>  // 做些操作</span></span>
<span class="line"><span>  emitter.setMaxListeners(Math.max(emitter.getMaxListeners() - 1, 0));</span></span>
<span class="line"><span>});</span></span></code></pre></div><h2 id="eventemitter-addlistener-eventname-listener" tabindex="-1">EventEmitter.addListener(eventName, listener)</h2><ul><li><code>eventName</code> {any}</li><li><code>listener</code> {Function}</li></ul><p>emitter.on(eventName, listener) 的别名.</p><h2 id="eventemitter-emit-eventname-args" tabindex="-1">EventEmitter.emit(eventName[, ...args])</h2><ul><li><code>eventName</code> {any}</li><li><code>args</code> {any}</li></ul><p>按监听器的注册顺序, 同步地调用每个注册到名为 eventName 事件的监听器, 并传入提供的参数.</p><p>如果事件有监听器, 则返回 true , 否则返回 false.</p><h2 id="eventemitter-eventnames" tabindex="-1">EventEmitter.eventNames()</h2><p>返回一个列出触发器已注册监听器的事件的数组. 数组中的值为字符串或符号.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const myEE = events.emitter();</span></span>
<span class="line"><span>myEE.on(&#39;foo&#39;, () =&gt; {});</span></span>
<span class="line"><span>myEE.on(&#39;bar&#39;, () =&gt; {});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const sym = Symbol(&#39;symbol&#39;);</span></span>
<span class="line"><span>myEE.on(sym, () =&gt; {});</span></span>
<span class="line"><span></span></span>
<span class="line"><span>console.log(myEE.eventNames());</span></span>
<span class="line"><span>// 打印: [ &#39;foo&#39;, &#39;bar&#39;, Symbol(symbol) ]</span></span></code></pre></div><h2 id="eventemitter-getmaxlisteners" tabindex="-1">EventEmitter.getMaxListeners()</h2><p>返回 EventEmitter 当前的最大监听器限制值, 该值可以通过 emitter.setMaxListeners(n) 设置或默认为 EventEmitter.defaultMaxListeners.</p><h2 id="eventemitter-listenercount-eventname" tabindex="-1">EventEmitter.listenerCount(eventName)</h2><ul><li><code>eventName</code> {string} 正在被监听的事件名</li></ul><p>返回正在监听名为 eventName 的事件的监听器的数量.</p><h2 id="eventemitter-listeners-eventname" tabindex="-1">EventEmitter.listeners(eventName)</h2><ul><li><code>eventName</code> {string}</li></ul><p>返回名为 eventName 的事件的监听器数组的副本.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.on(&#39;connection&#39;, (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;someone connected!&#39;);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>console.log(util.inspect(server.listeners(&#39;connection&#39;)));</span></span>
<span class="line"><span>// 打印: [ [Function] ]</span></span></code></pre></div><h2 id="eventemitter-on-eventname-listener" tabindex="-1">EventEmitter.on(eventName, listener)</h2><ul><li><code>eventName</code> {any} 事件名</li><li><code>listener</code> {Function} 回调函数</li></ul><p>添加 listener 函数到名为 eventName 的事件的监听器数组的末尾. 不会检查 listener 是否已被添加. 多次调用并传入相同的 eventName 和 listener 会导致 listener 被添加与调用多次.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.on(&#39;connection&#39;, (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;有连接！&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>返回一个 EventEmitter 引用, 可以链式调用.</p><p>默认情况下, 事件监听器会按照添加的顺序依次调用. emitter.prependListener() 方法可用于将事件监听器添加到监听器数组的开头.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const myEE = events.emitter();</span></span>
<span class="line"><span>myEE.on(&#39;foo&#39;, () =&gt; console.log(&#39;a&#39;));</span></span>
<span class="line"><span>myEE.prependListener(&#39;foo&#39;, () =&gt; console.log(&#39;b&#39;));</span></span>
<span class="line"><span>myEE.emit(&#39;foo&#39;);</span></span>
<span class="line"><span>// 打印:</span></span>
<span class="line"><span>//   b</span></span>
<span class="line"><span>//   a</span></span></code></pre></div><h2 id="eventemitter-once-eventname-listener" tabindex="-1">EventEmitter.once(eventName, listener)#</h2><ul><li><code>eventName</code> {any} 事件名</li><li><code>listener</code> {Function} 回调函数</li></ul><p>添加一个单次 listener 函数到名为 eventName 的事件. 下次触发 eventName 事件时, 监听器会被移除, 然后调用.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.once(&#39;connection&#39;, (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;首次调用！&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>返回一个 EventEmitter 引用, 可以链式调用.</p><p>默认情况下, 事件监听器会按照添加的顺序依次调用. emitter.prependOnceListener() 方法可用于将事件监听器添加到监听器数组的开头.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const myEE = events.emitter();</span></span>
<span class="line"><span>myEE.once(&#39;foo&#39;, () =&gt; console.log(&#39;a&#39;));</span></span>
<span class="line"><span>myEE.prependOnceListener(&#39;foo&#39;, () =&gt; console.log(&#39;b&#39;));</span></span>
<span class="line"><span>myEE.emit(&#39;foo&#39;);</span></span>
<span class="line"><span>// 打印:</span></span>
<span class="line"><span>//   b</span></span>
<span class="line"><span>//   a</span></span></code></pre></div><h2 id="eventemitter-prependlistener-eventname-listener" tabindex="-1">EventEmitter.prependListener(eventName, listener)</h2><ul><li><code>eventName</code> {any} 事件名</li><li><code>listener</code> {Function} 回调函数</li></ul><p>添加 listener 函数到名为 eventName 的事件的监听器数组的开头. 不会检查 listener 是否已被添加. 多次调用并传入相同的 eventName 和 listener 会导致 listener 被添加与调用多次.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.prependListener(&#39;connection&#39;, (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;有连接！&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>返回一个 EventEmitter 引用, 可以链式调用.</p><h2 id="eventemitter-prependoncelistener-eventname-listener" tabindex="-1">EventEmitter.prependOnceListener(eventName, listener)</h2><ul><li><code>eventName</code> {any} 事件名</li><li><code>listener</code> {Function} 回调函数</li></ul><p>添加一个单次 listener 函数到名为 eventName 的事件的监听器数组的开头. 下次触发 eventName 事件时, 监听器会被移除, 然后调用.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server.prependOnceListener(&#39;connection&#39;, (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;首次调用！&#39;);</span></span>
<span class="line"><span>});</span></span></code></pre></div><p>返回一个 EventEmitter 引用, 可以链式调用.</p><h2 id="eventemitter-removealllisteners-eventname" tabindex="-1">EventEmitter.removeAllListeners([eventName])</h2><ul><li><code>eventName</code> {any}</li></ul><p>移除全部或指定 eventName 的监听器.</p><p>注意, 在代码中移除其他地方添加的监听器是一个不好的做法, 尤其是当 EventEmitter 实例是其他组件或模块创建的.</p><p>返回一个 EventEmitter 引用, 可以链式调用.</p><h2 id="eventemitter-removelistener-eventname-listener" tabindex="-1">EventEmitter.removeListener(eventName, listener)</h2><ul><li><code>eventName</code> {any}</li><li><code>listener</code> {Function}</li></ul><p>从名为 eventName 的事件的监听器数组中移除指定的 listener.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const callback = (stream) =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;有连接！&#39;);</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span>server.on(&#39;connection&#39;, callback);</span></span>
<span class="line"><span>// ...</span></span>
<span class="line"><span>server.removeListener(&#39;connection&#39;, callback);</span></span></code></pre></div><p>removeListener 最多只会从监听器数组里移除一个监听器实例. 如果任何单一的监听器被多次添加到指定 eventName 的监听器数组中, 则必须多次调用 removeListener 才能移除每个实例.</p><p>注意, 一旦一个事件被触发, 所有绑定到它的监听器都会按顺序依次触发. 这意味着, 在事件触发后、最后一个监听器完成执行前, 任何 removeListener() 或 removeAllListeners() 调用都不会从 emit() 中移除它们. 随后的事件会像预期的那样发生.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const myEmitter = events.emitter();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const callbackA = () =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;A&#39;);</span></span>
<span class="line"><span>  myEmitter.removeListener(&#39;event&#39;, callbackB);</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>const callbackB = () =&gt; {</span></span>
<span class="line"><span>  console.log(&#39;B&#39;);</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>myEmitter.on(&#39;event&#39;, callbackA);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>myEmitter.on(&#39;event&#39;, callbackB);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// callbackA 移除了监听器 callbackB, 但它依然会被调用.</span></span>
<span class="line"><span>// 触发是内部的监听器数组为 [callbackA, callbackB]</span></span>
<span class="line"><span>myEmitter.emit(&#39;event&#39;);</span></span>
<span class="line"><span>// 打印:</span></span>
<span class="line"><span>//   A</span></span>
<span class="line"><span>//   B</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// callbackB 被移除了.</span></span>
<span class="line"><span>// 内部监听器数组为 [callbackA]</span></span>
<span class="line"><span>myEmitter.emit(&#39;event&#39;);</span></span>
<span class="line"><span>// 打印:</span></span>
<span class="line"><span>//   A</span></span></code></pre></div><p>因为监听器是使用内部数组进行管理的, 所以调用它会改变在监听器被移除后注册的任何监听器的位置索引. 虽然这不会影响监听器的调用顺序, 但意味着由 emitter.listeners() 方法返回的监听器数组副本需要被重新创建.</p><p>返回一个 EventEmitter 引用, 可以链式调用.</p><h2 id="eventemitter-setmaxlisteners-n" tabindex="-1">EventEmitter.setMaxListeners(n)</h2><ul><li><code>n</code> {number}</li></ul><p>默认情况下, 如果为特定事件添加了超过 10 个监听器, 则 EventEmitter 会打印一个警告. 此限制有助于寻找内存泄露. 但是, 并不是所有的事件都要被限为 10 个. emitter.setMaxListeners() 方法允许修改指定的 EventEmitter 实例的限制. 值设为 Infinity（或 0）表明不限制监听器的数量.</p><p>返回一个 EventEmitter 引用, 可以链式调用.</p><h1 id="events-broadcast-脚本间广播" tabindex="-1">events.broadcast: 脚本间广播</h1><p>脚本间通信除了使用engines模块提供的<code>ScriptEngine.emit()</code>方法以外, 也可以使用events模块提供的broadcast广播.</p><p>events.broadcast本身是一个EventEmitter, 但它的事件是在脚本间共享的, 所有脚本都能发送和监听这些事件；事件处理会在脚本主线程执行（后续可能加入函数<code>onThisThread(eventName, ...args)</code>来提供在其他线程执行的能力）.</p><p>例如在一个脚本发送一个广播hello:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.broadcast.emit(&quot;hello&quot;, &quot;小明&quot;);</span></span></code></pre></div><p>在其他脚本中监听并处理：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>events.broadcast.on(&quot;hello&quot;, function(name){</span></span>
<span class="line"><span>    toast(&quot;你好, &quot; + name);</span></span>
<span class="line"><span>});</span></span>
<span class="line"><span>//保持脚本运行</span></span>
<span class="line"><span>setInterval(()=&gt;{}, 1000);</span></span></code></pre></div>`,217)])])}const h=n(p,[["render",i]]);export{u as __pageData,h as default};
